draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // two stick figures
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.arc(W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 20);
  ctx.lineTo(W/4, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 60);
  ctx.lineTo(W/4 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/4, H/2 + 60);
  ctx.lineTo(W/4 + 20, H/2 + 80);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(W - W/4, H/2, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 20);
  ctx.lineTo(W - W/4, H/2 + 60);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 60);
  ctx.lineTo(W - W/4 - 20, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W - W/4, H/2 + 60);
  ctx.lineTo(W - W/4 + 20, H/2 + 80);
  ctx.stroke();

  // connection line
  ctx.beginPath();
  ctx.moveTo(W/4 + 20 + 10 * Math.sin(t), H/2 + 60);
  ctx.lineTo(W - W/4 - 20 - 10 * Math.sin(t), H/2 + 60);
  ctx.stroke();

  ctx.restore();
}
